#include <vector>
#include <numeric>

class Solution {
public:
    std::vector<int> maintenanceImpact(int n, std::vector<std::vector<int>>& edges, std::vector<int>& maintenance) {
        std::vector<int> ans;
        ans.reserve(maintenance.size());

        for (int rem_idx : maintenance) {
            std::vector<int> parent(n);
            std::iota(parent.begin(), parent.end(), 0);

            auto find = [&](auto& self, int x) -> int {
                return parent[x] == x ? x : parent[x] = self(self, parent[x]);
            };

            auto unite = [&](int x, int y) {
                int rx = find(find, x), ry = find(find, y);
                if (rx != ry) {
                    parent[rx] = ry;
                    return true;
                }
                return false;
            };

            int comps = n;
            for (size_t i = 0; i < edges.size(); ++i) {
                if ((int)i != rem_idx) {
                    if (unite(edges[i][0], edges[i][1])) comps--;
                }
            }
            ans.push_back(comps);
        }

        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] maintenanceImpact(int n, int[][] edges, int[] maintenance) {
        int[] ans = new int[maintenance.length];
        for (int q = 0; q < maintenance.length; q++) {
            int remIdx = maintenance[q];
            int[] parent = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;

            int comps = n;
            for (int i = 0; i < edges.length; i++) {
                if (i != remIdx) {
                    if (union(parent, edges[i][0], edges[i][1])) comps--;
                }
            }
            ans[q] = comps;
        }
        return ans;
    }

    private int find(int[] parent, int x) {
        if (parent[x] != x) parent[x] = find(parent, parent[x]);
        return parent[x];
    }

    private boolean union(int[] parent, int x, int y) {
        int rx = find(parent, x), ry = find(parent, y);
        if (rx != ry) {
            parent[rx] = ry;
            return true;
        }
        return false;
    }
}

