 * @param {number} n
 * @param {number[][]} edges
 * @param {number[]} maintenance
 * @return {number[]}
 */
var maintenanceImpact = function(n, edges, maintenance) {
    const ans = [];
    for (const remIdx of maintenance) {
        const parent = new Int32Array(n);
        for (let i = 0; i < n; i++) parent[i] = i;

        const find = (x) => {
            if (parent[x] !== x) parent[x] = find(parent[x]);
            return parent[x];
        };

        const union = (x, y) => {
            const rx = find(x), ry = find(y);
            if (rx !== ry) {
                parent[rx] = ry;
                return true;
            }
            return false;
        };

        let comps = n;
        for (let i = 0; i < edges.length; i++) {
            if (i !== remIdx) {
                if (union(edges[i][0], edges[i][1])) comps--;
            }
        }
        ans.push(comps);
    }
    return ans;
};
